(()=>{'use strict';
const groups={a:['bloom','arcade','cassette','cosmic'],b:['relay','metro','sakura','abyss'],c:['aurora','solstice','atlas','prism'],d:['loom','kinetic','tide']},groupOf=Object.fromEntries(Object.entries(groups).flatMap(([g,ids])=>ids.map(id=>[id,g]))),main=document.querySelector('#main'),hero=main?.querySelector('.hero'),apps=document.querySelector('#apps'),scriptURL=document.currentScript.src;if(!hero||!apps)return;
const appSection=apps.closest('section'),library=document.querySelector('#pins').closest('section');appSection.classList.add('ob-apps-panel');library.classList.add('ob-library-panels');document.querySelector('#pins').closest('.card').classList.add('ob-pins-panel');document.querySelector('#recents').closest('.card').classList.add('ob-recents-panel');
const surface=document.createElement('div');surface.id='ob-universe-apparatus';appSection.append(surface);const status=document.createElement('div');status.className='ob-layout-status';status.hidden=true;const message=document.createElement('span');message.setAttribute('role','status');const retry=document.createElement('button');retry.type='button';retry.textContent='Retry layout';status.append(message,retry);main.querySelector('.topline').append(status);
const plugins=new Map(),styles=new Map();let current='',desired='',cleanup,observer,appObserver,index=0,generation=0,alive=true;
const buttons=()=>Array.from(apps.querySelectorAll('button')).filter(b=>!b.disabled&&!b.hidden);const ctx={main,hero,apps,appSection,library,surface,buttons,selected:()=>buttons()[index]||buttons()[0],select(n){if(!alive)return;const a=buttons();if(a.length){index=(index+n+a.length)%a.length;mark();}},activate(){if(!alive)return;const b=ctx.selected();if(b?.isConnected&&!b.disabled)b.click();}};
function mark(){const a=buttons();if(index>=a.length)index=0;a.forEach((b,i)=>b.classList.toggle('ob-launch-selected',i===index));const out=surface.querySelector('[data-launch-name]');if(out)out.textContent=ctx.selected()?.querySelector('b,strong,h2,h3')?.textContent||ctx.selected()?.textContent||'Your apps';}
function load(group){if(styles.has(group))return styles.get(group).promise;const link=document.createElement('link');link.rel='stylesheet';link.href=new URL('universe-layouts-'+group+'.css',scriptURL).href;link.dataset.obLayoutGroup=group;const record={link,loaded:false};record.promise=new Promise((resolve,reject)=>{link.onload=()=>{record.loaded=true;resolve();};link.onerror=()=>{if(styles.get(group)===record)styles.delete(group);link.remove();reject(Error('LAYOUT_LOAD_FAILED'));};});styles.set(group,record);document.head.append(link);return record.promise;}
function commit(id){if(id!==current){const focused=surface.contains(document.activeElement)||status.contains(document.activeElement);cleanup?.();surface.replaceChildren();current=id;document.body.dataset.obUniverse=id;cleanup=plugins.get(id)?.mount?.(ctx);if(focused&&!document.querySelector('dialog[open],[role="dialog"]:not([hidden])'))document.querySelector('#universe-picker').focus();}status.hidden=true;mark();}
function select(id){desired=id;const token=++generation;if(current===id){status.hidden=true;return;}load(groupOf[id]).then(()=>{if(alive&&token===generation&&desired===id)commit(id);},()=>{if(!alive||token!==generation||desired!==id)return;message.textContent='This layout could not load. Your controls are still available.';status.hidden=false;});}
function sync(){const id=Array.from(hero.classList).find(c=>c.startsWith('universe-')&&Object.hasOwn(groupOf,c.slice(9)))?.slice(9);if(id&&id!==desired)select(id);mark();}
retry.onclick=()=>{if(desired)select(desired);};
function start(){alive=true;observer?.disconnect();appObserver?.disconnect();observer=new MutationObserver(sync);observer.observe(hero,{attributes:true,attributeFilter:['class']});appObserver=new MutationObserver(mark);appObserver.observe(apps,{childList:true});sync();}
apps.addEventListener('focusin',e=>{const i=buttons().indexOf(e.target.closest('button'));if(i>=0){index=i;mark();}});
window.OBStartLayouts=Object.freeze({register(id,plugin){if(!Object.hasOwn(groupOf,id))throw Error('Unknown Universe');plugins.set(id,plugin);if(current===id){cleanup?.();surface.replaceChildren();cleanup=plugin.mount?.(ctx);mark();}},refresh:sync});
addEventListener('pagehide',()=>{alive=false;generation++;observer?.disconnect();appObserver?.disconnect();cleanup?.();cleanup=null;});addEventListener('pageshow',e=>{if(!e.persisted)return;current='';desired='';start();});start();
})();
